(6608278, 986440, 30982, '<td valign="top">Wicked.  Probable more digital art to some than photography, but still quite wicked.  Quite the rush!</td>', 'Wicked.  Probable more digital art to some than photography, but still quite wicked.  Quite the rush!', '2011-12-01 22:23:36.000000', NULL, 1),
(6608279, 986186, 30982, '<td valign="top">Joyful, and wonderful light.</td>', 'Joyful, and wonderful light.', '2011-12-01 22:23:52.000000', NULL, 1),
(6608282, 985293, 30982, '<td valign="top">Intense.  Interesting title but really doesn''t connect with the photo for me.  I see more of a dream being realized - a letter from someone he''d nearly given up on.</td>', 'Intense.  Interesting title but really doesn''t connect with the photo for me.  I see more of a dream being realized - a letter from someone he''d nearly given up on.', '2011-12-01 22:25:26.000000', NULL, 1),
(6608285, 985294, 30982, '<td valign="top">Very interesting levels of connection with the audience, which, from what I can see, seems almost entirely male.  The white rectangle seems to have some mystical purpose, since after all someone is pointing to it.  All in all, a fun photograph to explore!</td>', 'Very interesting levels of connection with the audience, which, from what I can see, seems almost entirely male.  The white rectangle seems to have some mystical purpose, since after all someone is pointing to it.  All in all, a fun photograph to explore!', '2011-12-01 22:26:48.000000', NULL, 1),
(6608287, 986313, 30982, '<td valign="top">Excellent color combination!</td>', 'Excellent color combination!', '2011-12-01 22:27:26.000000', NULL, 1),
(6608291, 986246, 30982, '<td valign="top">Like a panorama.</td>', 'Like a panorama.', '2011-12-01 22:28:18.000000', NULL, 1),
(6608292, 985469, 30982, '<td valign="top">Nightmarish.  The hallway that never ends and leads nowhere.</td>', 'Nightmarish.  The hallway that never ends and leads nowhere.', '2011-12-01 22:28:37.000000', NULL, 1),
