(6609189, 985332, 25024, '<td valign="top">Great, a reflection only image! It works well with the ripple identifying it as a water reflection, I love the distortions resulting from it, hope you do well with this.</td>', 'Great, a reflection only image! It works well with the ripple identifying it as a water reflection, I love the distortions resulting from it, hope you do well with this.', '2011-12-02 19:14:02.000000', NULL, 1),
(6609191, 983957, 25024, '<td valign="top">Well at least its not all over the beach! The near mono of the main image works well in contrast to the mainly clear but some coloured bottles on the spike, good luck with this</td>', 'Well at least its not all over the beach! The near mono of the main image works well in contrast to the mainly clear but some coloured bottles on the spike, good luck with this', '2011-12-02 19:16:16.000000', NULL, 1),
(6609200, 985605, 33672, '<td valign="top">Very symbolic.  Nicely done!</td>', 'Very symbolic.  Nicely done!', '2011-12-02 19:32:55.000000', NULL, 1),
