INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6609211, 985469, 23484, '<td valign="top">Nice vanishing point.</td>', 'Nice vanishing point.', '2011-12-02 19:45:05.000000', NULL, 1),
(6609213, 985329, 23484, '<td valign="top">Wow! 10</td>', 'Wow! 10', '2011-12-02 19:46:15.000000', NULL, 1),
(6609214, 986291, 23484, '<td valign="top">The grain goes very well with this.</td>', 'The grain goes very well with this.', '2011-12-02 19:46:32.000000', NULL, 1),
(6609215, 985355, 23484, '<td valign="top">The pastel colors are great. Neat shot.</td>', 'The pastel colors are great. Neat shot.', '2011-12-02 19:47:09.000000', NULL, 1),
(6609216, 986332, 23484, '<td valign="top">I love that old architecture.</td>', 'I love that old architecture.', '2011-12-02 19:47:33.000000', NULL, 1),
(6609261, 985959, 57447, '<td valign="top">Great room.</td>', 'Great room.', '2011-12-02 22:04:54.000000', NULL, 1),
(6609262, 986119, 57447, '<td valign="top">Jackabago</td>', 'Jackabago', '2011-12-02 22:08:21.000000', NULL, 1),
(6609264, 985649, 57447, '<td valign="top">You found a great place to photograph and you did it justice.</td>', 'You found a great place to photograph and you did it justice.', '2011-12-02 22:11:08.000000', NULL, 1),
(6609268, 986078, 83313, '<td valign="top">Not a clue what the title means. It does appear vaguely Asian, but seems to actually be in a code. I haven''t cracked it, however. Extra pointage simply to neutralize the low vote you will get from someone else over it.</td>', 'Not a clue what the title means. It does appear vaguely Asian, but seems to actually be in a code. I haven''t cracked it, however. Extra pointage simply to neutralize the low vote you will get from someone else over it.', '2011-12-02 22:19:03.000000', NULL, 1),
(6609277, 983284, 91342, '<td valign="top">I''m torn between man in window and the tower.  It seems to be two different images.  Try cropping out either the lower portion with window or at the distant horizon to emphasize the man.</td>', 'I''m torn between man in window and the tower.  It seems to be two different images.  Try cropping out either the lower portion with window or at the distant horizon to emphasize the man.', '2011-12-02 22:47:27.000000', NULL, 1),
(6609278, 983934, 91342, '<td valign="top">I really like the two sides of the window.</td>', 'I really like the two sides of the window.', '2011-12-02 22:48:22.000000', NULL, 1),
(6609279, 985355, 91342, '<td valign="top">A bit too surreal for my tastes.  Nice image though.</td>', 'A bit too surreal for my tastes.  Nice image though.', '2011-12-02 22:48:42.000000', NULL, 1),
(6609281, 985706, 91342, '<td valign="top">The title makes me look for something amongst the trees.  Seems to be a bit too much halo along the trees.  Cropping some of the top would bring more focus to the trees.</td>', 'The title makes me look for something amongst the trees.  Seems to be a bit too much halo along the trees.  Cropping some of the top would bring more focus to the trees.', '2011-12-02 22:50:35.000000', NULL, 1),
(6609282, 986150, 91342, '<td valign="top">Cloning the window frame into the green background would be nice. (I think that is legal.)  Cute image.</td>', 'Cloning the window frame into the green background would be nice. (I think that is legal.)  Cute image.', '2011-12-02 22:51:51.000000', NULL, 1),
(6609283, 985921, 91342, '<td valign="top">nice capture of an elderly friend.</td>', 'nice capture of an elderly friend.', '2011-12-02 22:52:14.000000', NULL, 1),
(6609284, 986025, 91342, '<td valign="top">Too much sky for my tastes.</td>', 'Too much sky for my tastes.', '2011-12-02 22:52:39.000000', NULL, 1),
(6609285, 983413, 91342, '<td valign="top">Don''t understand the title.  I like the image.</td>', 'Don''t understand the title.  I like the image.', '2011-12-02 22:53:06.000000', NULL, 1),
(6609286, 983620, 91342, '<td valign="top">Great presentation/composition.</td>', 'Great presentation/composition.', '2011-12-02 22:54:01.000000', NULL, 1),
(6609289, 986031, 91342, '<td valign="top">I''m confused by blue and white lighting.</td>', 'I''m confused by blue and white lighting.', '2011-12-02 22:55:16.000000', NULL, 1),
(6609290, 986385, 91342, '<td valign="top">Try cropping some off the right side.  The brightness is distracting.</td>', 'Try cropping some off the right side.  The brightness is distracting.', '2011-12-02 22:56:06.000000', NULL, 1),
(6609291, 986399, 91342, '<td valign="top">Wonderful title for this image.  I like the black border presentation.</td>', 'Wonderful title for this image.  I like the black border presentation.', '2011-12-02 22:57:17.000000', NULL, 1),
(6609301, 986401, 91342, '<td valign="top">Sky processing is distracting.</td>', 'Sky processing is distracting.', '2011-12-02 23:35:31.000000', NULL, 1),
(6609302, 986435, 91342, '<td valign="top">Portrait on the wall is a bit distracting.  Still, as very nice image.</td>', 'Portrait on the wall is a bit distracting.  Still, as very nice image.', '2011-12-02 23:37:58.000000', NULL, 1),
(6609306, 986272, 91342, '<td valign="top">The title confuses me.</td>', 'The title confuses me.', '2011-12-02 23:43:17.000000', NULL, 1),
(6609307, 986252, 91342, '<td valign="top">Background is distracting.</td>', 'Background is distracting.', '2011-12-02 23:46:34.000000', NULL, 1),
(6609343, 984009, 47470, '<td valign="top">I didn''t notice the clouds until I read your title.  I was distracted by the distortion, which makes me think the distortion wasn''t a good choice for this image since it takes away from the part that you wanted the audience to focus on.</td>', 'I didn''t notice the clouds until I read your title.  I was distracted by the distortion, which makes me think the distortion wasn''t a good choice for this image since it takes away from the part that you wanted the audience to focus on.', '2011-12-03 00:16:41.000000', NULL, 1),
(6609347, 986342, 47470, '<td valign="top">Although this scene is beautiful, I think you tried to include too many things in it, which makes the image feel a  bit cluttered to me.  I would have cropped it just to the left of the road to keep the road and the right half of the image.  That part of the image has light hitting it, which adds interest and makes that part of the image brighter and more attractive to the eye.  The crop that I described would also make the road more of a leading line while putting the steeple on the third line to balance out the vertical of the road.</td>', 'Although this scene is beautiful, I think you tried to include too many things in it, which makes the image feel a  bit cluttered to me.  I would have cropped it just to the left of the road to keep the road and the right half of the image.  That part of the image has light hitting it, which adds interest and makes that part of the image brighter and more attractive to the eye.  The crop that I described would also make the road more of a leading line while putting the steeple on the third line to balance out the vertical of the road.', '2011-12-03 00:21:13.000000', NULL, 1),
(6609354, 985603, 47470, '<td valign="top">I assume you cropped this way because there was something on the ground that wouldn''t have looked nice in your image.  Still, I can''t help but wish the crop had been moved down a bit to see what''s going on down there at human level too.</td>', 'I assume you cropped this way because there was something on the ground that wouldn''t have looked nice in your image.  Still, I can''t help but wish the crop had been moved down a bit to see what''s going on down there at human level too.', '2011-12-03 00:43:48.000000', NULL, 1),
(6609356, 985730, 47470, '<td valign="top">I would have preferred a tighter crop on the left side so that the bird wasn''t pinned so close to the middle.</td>', 'I would have preferred a tighter crop on the left side so that the bird wasn''t pinned so close to the middle.', '2011-12-03 00:44:34.000000', NULL, 1),
(6609357, 986370, 47470, '<td valign="top">You get an extra point for having such an unexpected, yet fitting, title for a subject that is entered several times a week here.  Thanks for spicing up this building abstract with an interesting title.</td>', 'You get an extra point for having such an unexpected, yet fitting, title for a subject that is entered several times a week here.  Thanks for spicing up this building abstract with an interesting title.', '2011-12-03 00:45:58.000000', NULL, 1),
(6609360, 983572, 47470, '<td valign="top">Gorgeous tones and colors in the water.</td>', 'Gorgeous tones and colors in the water.', '2011-12-03 00:47:11.000000', NULL, 1),
(6609362, 986184, 30982, '<td valign="top">Oh my gosh!!  How magical!  My favorite for this month - thanks so much for sharing it!</td>', 'Oh my gosh!!  How magical!  My favorite for this month - thanks so much for sharing it!', '2011-12-03 00:50:13.000000', NULL, 1),
(6609363, 983934, 30982, '<td valign="top">Love this.  The silhouettes outside versus the window-faded people inside (and that hat!) and the multitude of signs offering so many options.  Add some nice vertical and horizontal lines and you have yourself a very good photograph!</td>', 'Love this.  The silhouettes outside versus the window-faded people inside (and that hat!) and the multitude of signs offering so many options.  Add some nice vertical and horizontal lines and you have yourself a very good photograph!', '2011-12-03 00:50:17.000000', NULL, 1),
(6609364, 986165, 30982, '<td valign="top">Love me a good cow picture.  :-)</td>', 'Love me a good cow picture.  :-)', '2011-12-03 00:50:55.000000', NULL, 1),
(6609365, 984993, 30982, '<td valign="top">Makes me smile.</td>', 'Makes me smile.', '2011-12-03 00:50:57.000000', NULL, 1),
(6609366, 985734, 30982, '<td valign="top">Very otherwordly yielding of a very normal situation.  I like it a lot!</td>', 'Very otherwordly yielding of a very normal situation.  I like it a lot!', '2011-12-03 00:51:48.000000', NULL, 1),
(6609380, 982638, 128323, '<td valign="top">What a capture!  I love how the exhaust just churns up the otherwise serene background!  Great shot!</td>', 'What a capture!  I love how the exhaust just churns up the otherwise serene background!  Great shot!', '2011-12-03 02:11:43.000000', NULL, 1),
(6609381, 986308, 128323, '<td valign="top">Very sad.</td>', 'Very sad.', '2011-12-03 02:12:41.000000', NULL, 1),
(6609387, 985354, 128323, '<td valign="top">Brilliant shot!</td>', 'Brilliant shot!', '2011-12-03 02:21:58.000000', NULL, 1),
(6609398, 986076, 54446, '<td valign="top">This is a truly compelling image.  The monochrome works great here.  Superb lighting and pose.  The image is so good, it transcends the post processing.   A joy to view.  One of my top picks in this FS.  I will be disappointed if this does not ribbon.</td>', 'This is a truly compelling image.  The monochrome works great here.  Superb lighting and pose.  The image is so good, it transcends the post processing.   A joy to view.  One of my top picks in this FS.  I will be disappointed if this does not ribbon.', '2011-12-03 05:31:13.000000', NULL, 1),
(6609399, 985971, 54446, '<td valign="top">This is one of my top picks in this FS.  Amazing light and detail.  Magical, it is.</td>', 'This is one of my top picks in this FS.  Amazing light and detail.  Magical, it is.', '2011-12-03 05:32:37.000000', NULL, 1),
(6609400, 986084, 54446, '<td valign="top">Well done.  Excellent composition.  Spectacular color and detail.  One forgets you (probably) shot this through aquarium glass.</td>', 'Well done.  Excellent composition.  Spectacular color and detail.  One forgets you (probably) shot this through aquarium glass.', '2011-12-03 05:34:01.000000', NULL, 1),
(6609401, 982638, 54446, '<td valign="top">Very cool image.  Excellent clarity and detail.</td>', 'Very cool image.  Excellent clarity and detail.', '2011-12-03 05:35:43.000000', NULL, 1),
(6609403, 986166, 54446, '<td valign="top">Professional shot.  Great expressions and lighting.  The BG distracts me, but the quality capture of the subjects overcomes the overwork behind.  One of my top picks.  I''m bumping this up on this 2nd look. (10)</td>', 'Professional shot.  Great expressions and lighting.  The BG distracts me, but the quality capture of the subjects overcomes the overwork behind.  One of my top picks.  I''m bumping this up on this 2nd look. (10)', '2011-12-03 05:39:07.000000', NULL, 1),
(6609413, 985638, 131851, '<td valign="top">this is the one that moves me most</td>', 'this is the one that moves me most', '2011-12-03 06:57:08.000000', NULL, 1),
(6609520, 985792, 47470, '<td valign="top">The mottled background has a wonderful texture, but I would have preferred if the leaf was a bit sharper/crisper.  It looks like you oversaturated the colors because the branch is cyan.</td>', 'The mottled background has a wonderful texture, but I would have preferred if the leaf was a bit sharper/crisper.  It looks like you oversaturated the colors because the branch is cyan.', '2011-12-03 10:48:45.000000', NULL, 1),
(6609527, 986031, 47470, '<td valign="top">I would have preferred if this wasn''t so saturated that it emphasizes the difference between the cyan of the shade and the slight warm tones in the sunlight or if it was color toned to just one of those colors.</td>', 'I would have preferred if this wasn''t so saturated that it emphasizes the difference between the cyan of the shade and the slight warm tones in the sunlight or if it was color toned to just one of those colors.', '2011-12-03 10:55:17.000000', NULL, 1),
(6609530, 986236, 47470, '<td valign="top">The processing makes the image feel...soft.  Not soft as in unsharp.  I can''t feel the rough texture of the bricks or of the dirt or of anything else because it feels...soft.  I''m not sure if I''m explaining myself well.  I guess I just don''t think the processing matches the subject or the atmosphere of the image.</td>', 'The processing makes the image feel...soft.  Not soft as in unsharp.  I can''t feel the rough texture of the bricks or of the dirt or of anything else because it feels...soft.  I''m not sure if I''m explaining myself well.  I guess I just don''t think the processing matches the subject or the atmosphere of the image.', '2011-12-03 11:03:46.000000', NULL, 1),
(6609623, 985033, 63918, '<td valign="top">Great face and hypnotic look! Very good lighting!..maybe a tiny bit of fill on the right but that is just personal preference and might not have worked.</td>', 'Great face and hypnotic look! Very good lighting!..maybe a tiny bit of fill on the right but that is just personal preference and might not have worked.', '2011-12-03 12:56:55.000000', NULL, 1),
(6609628, 986243, 76335, '<td valign="top">I can''t see him, but he can''t see me either. Nice atmosphere.</td>', 'I can''t see him, but he can''t see me either. Nice atmosphere.', '2011-12-03 13:00:21.000000', NULL, 1),
(6609631, 983499, 76335, '<td valign="top">Brutally honest with a warm coolness. Good.</td>', 'Brutally honest with a warm coolness. Good.', '2011-12-03 13:01:25.000000', NULL, 1),
(6609632, 985033, 76335, '<td valign="top">Love the dramatic lighting which teases us with the delicacy of her features. Nicely done.</td>', 'Love the dramatic lighting which teases us with the delicacy of her features. Nicely done.', '2011-12-03 13:05:24.000000', NULL, 1),
(6609633, 986385, 76335, '<td valign="top">The tones in her face seem flat for some reason.</td>', 'The tones in her face seem flat for some reason.', '2011-12-03 13:06:00.000000', NULL, 1),
(6609635, 983572, 76335, '<td valign="top">So delicately balanced. A wonderful composition.</td>', 'So delicately balanced. A wonderful composition.', '2011-12-03 13:07:53.000000', NULL, 1),
(6609636, 986148, 76335, '<td valign="top">I only wish you had gottten closer. But I''m myopic that way. Good.</td>', 'I only wish you had gottten closer. But I''m myopic that way. Good.', '2011-12-03 13:09:41.000000', NULL, 1),
(6609643, 986374, 115307, '<td valign="top">I really like this. It is very intriguing, with the different layers of the photograph. The eyes seem a bit overprocessed, and yet it is precisely that that draws me into the picture.</td>', 'I really like this. It is very intriguing, with the different layers of the photograph. The eyes seem a bit overprocessed, and yet it is precisely that that draws me into the picture.', '2011-12-03 13:25:40.000000', NULL, 1),
(6609644, 985355, 140777, '<td valign="top">Wonderful shot.</td>', 'Wonderful shot.', '2011-12-03 13:26:05.000000', NULL, 1),
(6609645, 986184, 115307, '<td valign="top">So much joy in this picture :-) It looks like the girl is taking off in flight to the moon and beyond. Wonderful moment. 8</td>', 'So much joy in this picture :-) It looks like the girl is taking off in flight to the moon and beyond. Wonderful moment. 8', '2011-12-03 13:26:31.000000', NULL, 1),
(6609646, 986273, 115307, '<td valign="top">I really like the mood created by the processing here and the way the road leads the eye through and into the picture.</td>', 'I really like the mood created by the processing here and the way the road leads the eye through and into the picture.', '2011-12-03 13:27:52.000000', NULL, 1),
(6609648, 986151, 115307, '<td valign="top">Lovely portrait, as was your last one in the defining feature challenge. She really does have gorgeous eyes, and I just love that hat. My only dislike is the fuzzy thing (scarf?) she is wearing, I think it distracts the viewer a bit too much.</td>', 'Lovely portrait, as was your last one in the defining feature challenge. She really does have gorgeous eyes, and I just love that hat. My only dislike is the fuzzy thing (scarf?) she is wearing, I think it distracts the viewer a bit too much.', '2011-12-03 13:29:43.000000', NULL, 1),
(6609649, 984009, 115307, '<td valign="top">I wish this was a bit bigger, as this is a lovely landscape photograph. I like the wide perspective and how the trees curve.</td>', 'I wish this was a bit bigger, as this is a lovely landscape photograph. I like the wide perspective and how the trees curve.', '2011-12-03 13:30:46.000000', NULL, 1),
(6609650, 986288, 115307, '<td valign="top">Lovely. This looks more like a painting than a photograph. I could definitely see this hanging on somebody''s wall. I love the contrast between the warm sky and the cool fog, and the horses create the perfect added point of interest.<br/>I just really connect with this. 10 from me</td>', 'Lovely. This looks more like a painting than a photograph. I could definitely see this hanging on somebody''s wall. I love the contrast between the warm sky and the cool fog, and the horses create the perfect added point of interest.I just really connect with this. 10 from me', '2011-12-03 13:32:42.000000', NULL, 1),
(6609651, 986342, 140777, '<td valign="top">Such a great colors! Wonderful shot.</td>', 'Such a great colors! Wonderful shot.', '2011-12-03 13:33:18.000000', NULL, 1),
(6609652, 986293, 115307, '<td valign="top">Wow, the blimp almost makes this look surreal. I really like this. The exposure is perfect and the picture is sharp and yet so very smooth. 9</td>', 'Wow, the blimp almost makes this look surreal. I really like this. The exposure is perfect and the picture is sharp and yet so very smooth. 9', '2011-12-03 13:34:06.000000', NULL, 1),
(6609654, 985354, 140777, '<td valign="top">Great lines and colors!</td>', 'Great lines and colors!', '2011-12-03 13:42:08.000000', NULL, 1),
(6609655, 985870, 140777, '<td valign="top">:) Nice catch!</td>', ':) Nice catch!', '2011-12-03 13:44:36.000000', NULL, 1),
(6609669, 981938, 24486, '<td valign="top">I bet it was cold shooting this but it was worth it to get a shot like this.</td>', 'I bet it was cold shooting this but it was worth it to get a shot like this.', '2011-12-03 14:47:04.000000', NULL, 1),
(6609670, 986365, 24486, '<td valign="top">So true. Made me laugh when I read the title.</td>', 'So true. Made me laugh when I read the title.', '2011-12-03 14:48:38.000000', NULL, 1),
(6609671, 985595, 24486, '<td valign="top">Excellant detail.</td>', 'Excellant detail.', '2011-12-03 14:50:23.000000', NULL, 1),
(6609672, 982765, 24486, '<td valign="top">Nice timing. The panoramic crop really helps this photograph</td>', 'Nice timing. The panoramic crop really helps this photograph', '2011-12-03 14:51:52.000000', NULL, 1),
(6609677, 985867, 24486, '<td valign="top">Very eye catching. Wonderful Detail</td>', 'Very eye catching. Wonderful Detail', '2011-12-03 15:00:54.000000', NULL, 1),
(6609679, 985734, 24486, '<td valign="top">This is quite unique. I would be interested to know how you achieved this.</td>', 'This is quite unique. I would be interested to know how you achieved this.', '2011-12-03 15:06:06.000000', NULL, 1),
(6609722, 985605, 81362, '<td valign="top">Fantastic multiple layers of hints and symbols: padlock, inexpensive furniture, white hair, glasses, all capturing attention and keeping me looking, enhanced by the unconventional division into 2 rectangles and interesting light. 10.</td>', 'Fantastic multiple layers of hints and symbols: padlock, inexpensive furniture, white hair, glasses, all capturing attention and keeping me looking, enhanced by the unconventional division into 2 rectangles and interesting light. 10.', '2011-12-03 16:46:59.000000', NULL, 1),
(6609724, 985959, 81362, '<td valign="top">Getting strict symmetry right is harder than most people think. Well done.</td>', 'Getting strict symmetry right is harder than most people think. Well done.', '2011-12-03 16:48:12.000000', NULL, 1),
(6609725, 986151, 81362, '<td valign="top">Beautiful portrait light.</td>', 'Beautiful portrait light.', '2011-12-03 16:48:53.000000', NULL, 1),
(6609727, 986298, 81362, '<td valign="top">Christmas wrapping in nature. Red/green with touches of purple elevate this above most peeling bark compositions (although would be interesting to see in black and white too).</td>', 'Christmas wrapping in nature. Red/green with touches of purple elevate this above most peeling bark compositions (although would be interesting to see in black and white too).', '2011-12-03 16:50:18.000000', NULL, 1),
(6609731, 986257, 81362, '<td valign="top">Not the too-often seen cat as convenient subject. Nice framing and focus.</td>', 'Not the too-often seen cat as convenient subject. Nice framing and focus.', '2011-12-03 16:56:52.000000', NULL, 1),
(6609742, 985771, 25024, '<td valign="top">All credit to you for producing a creative abstract but probably a bit too abstract for me but I''m sure there will be others here who will show their appreciation, good luck</td>', 'All credit to you for producing a creative abstract but probably a bit too abstract for me but I''m sure there will be others here who will show their appreciation, good luck', '2011-12-03 17:10:07.000000', NULL, 1),
(6609744, 985164, 25024, '<td valign="top">I like the unusual approach you''ve adopted that makes it stand out from just another flower shot, good lighting and exposure, hope you do well with it</td>', 'I like the unusual approach you''ve adopted that makes it stand out from just another flower shot, good lighting and exposure, hope you do well with it', '2011-12-03 17:12:00.000000', NULL, 1),
(6609745, 985599, 25024, '<td valign="top">a very colourful image</td>', 'a very colourful image', '2011-12-03 17:12:33.000000', NULL, 1),
(6609747, 986313, 25024, '<td valign="top">the exaggerated angle makes the image more interesting</td>', 'the exaggerated angle makes the image more interesting', '2011-12-03 17:13:35.000000', NULL, 1),
